use vstd::prelude::*;

verus! {

/// Return the index of the first occurrence of the maximum element
/// in a non‐empty vector `a`.
/// Postconditions:
///   - `idx` is in bounds,
///   - `a[idx]` is >= every element of `a`,
///   - and no earlier position ties that maximum.
fn nanargmax(a: Vec<i8>) -> (idx: usize)
    requires
        a.len() > 0,
    ensures
        idx < a.len(),
        forall |j: usize| j < a.len() ==> a[idx] >= a[j],
        forall |j: usize| j < idx     ==> a[j] <  a[idx],
{
    let n = a.len();
    // initialize to the first element
    let mut max_idx: usize = 0;
    let mut max_val: i8     = a[0];
    let mut i: usize        = 1;

    // scan from i=1 up to n
    while i < n
        invariant
            // we have processed exactly [0..i)
            1 <= i <= n,
            // max_idx is in [0..i)
            max_idx < i,
            // and indeed max_val == a[max_idx]
            max_val == a[max_idx],
            // and among [0..i), a[max_idx] is the maximum,
            forall |j: usize| j < i         ==> a[max_idx] >= a[j],
            // and max_idx is the *first* place that maximum occurs,
            forall |j: usize| j < max_idx   ==> a[j] <  a[max_idx],
        decreases n - i,
    {
        let ai = a[i];
        if ai > max_val {
            // found a strictly larger value, update both value and index
            max_val = ai;
            max_idx = i;
        }
        // advance to the next position
        i = i + 1;
    }

    // when i==n, max_idx still points to the first global maximum
    max_idx
}

} // end verus!

